-- Table definitions extracted from supplied migrations; no production data.
CREATE TABLE public.rooms (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, name text NOT NULL, status text NOT NULL DEFAULT 'setup' CHECK (status IN ('setup', 'live', 'paused', 'complete')), timer_seconds integer NOT NULL DEFAULT 30 CHECK (timer_seconds BETWEEN 5 AND 300), min_bid integer NOT NULL DEFAULT 1 CHECK (min_bid > 0), bid_increment integer NOT NULL DEFAULT 1 CHECK (bid_increment > 0), active_player_id uuid, active_bid integer NOT NULL DEFAULT 0 CHECK (active_bid >= 0), active_bidder_team_id uuid, auction_ends_at timestamptz, pause_remaining_seconds integer, sold_count integer NOT NULL DEFAULT 0 CHECK (sold_count >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.teams (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, name text NOT NULL, starting_budget integer NOT NULL CHECK (starting_budget >= 0), remaining_budget integer NOT NULL CHECK (remaining_budget >= 0), sort_order integer NOT NULL, UNIQUE (room_id, name), UNIQUE (room_id, sort_order));
CREATE TABLE public.players (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, rank integer NOT NULL, name text NOT NULL, nfl_team text NOT NULL, position text NOT NULL CHECK (position IN ('QB', 'RB', 'WR', 'TE')), note text, status text NOT NULL DEFAULT 'queued' CHECK (status IN ('available', 'queued', 'active', 'sold')), queue_order integer, sold_team_id uuid REFERENCES public.teams (id), sold_price integer, UNIQUE (room_id, rank));
CREATE TABLE public.bids (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, player_id uuid NOT NULL REFERENCES public.players (id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES public.teams (id) ON DELETE CASCADE, amount integer NOT NULL CHECK (amount > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.sales (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, player_id uuid NOT NULL REFERENCES public.players (id), team_id uuid NOT NULL REFERENCES public.teams (id), price integer NOT NULL CHECK (price > 0), sold_at timestamptz NOT NULL DEFAULT now(), undone boolean NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS public.league_seasons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, season_year integer NOT NULL, status text NOT NULL DEFAULT 'active' CHECK (status IN ('setup', 'active', 'complete', 'archived')), roster_limit integer NOT NULL DEFAULT 18 CHECK (roster_limit BETWEEN 1 AND 100), salary_cap_points integer NOT NULL DEFAULT 100 CHECK (salary_cap_points BETWEEN 1 AND 10000), is_current boolean NOT NULL DEFAULT FALSE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (room_id, season_year));
CREATE TABLE IF NOT EXISTS public.league_rule_settings (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, rule_key text NOT NULL, category text NOT NULL, label text NOT NULL, numeric_value numeric, text_value text, boolean_value boolean, unit text, sort_order integer NOT NULL DEFAULT 0, locked boolean NOT NULL DEFAULT FALSE, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, rule_key));
CREATE TABLE IF NOT EXISTS public.redistribution_rules (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, bracket text NOT NULL CHECK (bracket IN ('championship', 'consolation')), finish integer NOT NULL CHECK (finish BETWEEN 1 AND 6), label text NOT NULL, percentage numeric(7, 3) NOT NULL CHECK (percentage >= 0 AND percentage <= 100), sort_order integer NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, bracket, finish));
CREATE TABLE IF NOT EXISTS public.contract_options (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, years integer NOT NULL CHECK (years BETWEEN 1 AND 10), cap_cost integer NOT NULL CHECK (cap_cost >= 0), active boolean NOT NULL DEFAULT TRUE, UNIQUE (season_id, years));
CREATE TABLE IF NOT EXISTS public.league_contracts (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES public.teams (id), player_key text NOT NULL, player_name text NOT NULL, start_year integer NOT NULL, end_year integer NOT NULL, length_years integer NOT NULL CHECK (length_years BETWEEN 1 AND 10), cap_cost integer NOT NULL CHECK (cap_cost >= 0), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'expired', 'released', 'traded', 'void')), source text NOT NULL DEFAULT 'import', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, player_key));
CREATE TABLE IF NOT EXISTS public.league_deadlines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, title text NOT NULL, deadline_type text NOT NULL DEFAULT 'general', due_at timestamptz NOT NULL, auto_lock boolean NOT NULL DEFAULT TRUE, allow_commish_override boolean NOT NULL DEFAULT TRUE, status text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'closed', 'completed', 'cancelled')), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.league_deadline_team_status (deadline_id uuid NOT NULL REFERENCES public.league_deadlines (id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES public.teams (id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'submitted', 'late', 'waived')), submitted_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (deadline_id, team_id));
CREATE TABLE IF NOT EXISTS public.league_finance_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, team_id uuid REFERENCES public.teams (id), category text NOT NULL CHECK (category IN ('dues', 'prize', 'expense', 'adjustment', 'other')), description text NOT NULL, amount_cents integer NOT NULL, status text NOT NULL DEFAULT 'due' CHECK (status IN ('due', 'paid', 'waived')), due_at date, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.league_audit_log (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, actor_team_id uuid REFERENCES public.teams (id), action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT CAST('{}' AS jsonb), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.league_roster_entries (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, team_id uuid NOT NULL REFERENCES public.teams (id), player_key text NOT NULL, player_name text NOT NULL, nfl_team text, position text, acquisition_type text NOT NULL DEFAULT 'current_roster' CHECK (acquisition_type IN ('current_roster', 'contract', 'rookie', 'auction', 'supplemental', 'rights_claim', 'phase3', 'manual')), acquisition_price integer, source_key text, active boolean NOT NULL DEFAULT TRUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (room_id, player_key));
CREATE TABLE IF NOT EXISTS public.league_future_picks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, draft_year integer NOT NULL, draft_type text NOT NULL CHECK (draft_type IN ('rookie', 'supplemental')), round integer NOT NULL CHECK (round BETWEEN 1 AND 10), original_team_id uuid NOT NULL REFERENCES public.teams (id), owner_team_id uuid NOT NULL REFERENCES public.teams (id), status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'used', 'forfeited')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (room_id, draft_year, draft_type, round, original_team_id));
CREATE TABLE IF NOT EXISTS public.league_rookie_rights (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, player_key text NOT NULL, player_name text NOT NULL, rookie_draft_year integer NOT NULL, owner_team_id uuid REFERENCES public.teams (id), origin text NOT NULL DEFAULT 'rookie_draft', status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'extinguished', 'expired')), extinguished_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (room_id, player_key));
CREATE TABLE IF NOT EXISTS public.league_trades (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, proposer_team_id uuid NOT NULL REFERENCES public.teams (id), partner_team_id uuid NOT NULL REFERENCES public.teams (id), status text NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed', 'pending_commish', 'approved', 'rejected', 'denied', 'cancelled')), note text, proposed_at timestamptz NOT NULL DEFAULT now(), accepted_at timestamptz, decided_at timestamptz, commissioner_team_id uuid REFERENCES public.teams (id), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (proposer_team_id <> partner_team_id));
CREATE TABLE IF NOT EXISTS public.league_trade_assets (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, trade_id uuid NOT NULL REFERENCES public.league_trades (id) ON DELETE CASCADE, direction text NOT NULL CHECK (direction IN ('proposer_to_partner', 'partner_to_proposer')), asset_type text NOT NULL CHECK (asset_type IN ('player', 'rookie_rights', 'rookie_pick', 'supplemental_pick', 'bid_dollars')), asset_key text, player_name text, pick_id uuid REFERENCES public.league_future_picks (id), bid_amount integer, details jsonb NOT NULL DEFAULT CAST('{}' AS jsonb), created_at timestamptz NOT NULL DEFAULT now(), CHECK ((asset_type = 'bid_dollars' AND bid_amount IS NOT NULL AND bid_amount > 0) OR asset_type <> 'bid_dollars'));
CREATE TABLE IF NOT EXISTS public.league_game_settings (season_id uuid PRIMARY KEY REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, current_week integer NOT NULL DEFAULT 1 CHECK (current_week BETWEEN 1 AND 25), regular_season_weeks integer, playoff_start_week integer, lineup_lock_mode text NOT NULL DEFAULT 'individual_game_start', scoring_source text NOT NULL DEFAULT 'pending', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.league_lineup_slots (id bigserial PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, slot_code text NOT NULL, label text NOT NULL, slot_order integer NOT NULL, allowed_positions text[] NOT NULL, active boolean NOT NULL DEFAULT TRUE, UNIQUE (season_id, slot_code), UNIQUE (season_id, slot_order));
CREATE TABLE IF NOT EXISTS public.league_week_states (id bigserial PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, week integer NOT NULL CHECK (week BETWEEN 1 AND 25), phase text NOT NULL DEFAULT 'regular' CHECK (phase IN ('regular', 'playoffs', 'championship', 'consolation')), status text NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled', 'live', 'final')), starts_at timestamptz, finalized_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, week));
CREATE TABLE IF NOT EXISTS public.league_schedule (id bigserial PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, week integer NOT NULL CHECK (week BETWEEN 1 AND 25), matchup_no integer NOT NULL, phase text NOT NULL DEFAULT 'regular' CHECK (phase IN ('regular', 'playoffs', 'championship', 'consolation')), home_team_id uuid NOT NULL REFERENCES public.teams (id) ON DELETE CASCADE, away_team_id uuid NOT NULL REFERENCES public.teams (id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, week, matchup_no), CHECK (home_team_id <> away_team_id));
CREATE TABLE IF NOT EXISTS public.league_lineups (id bigserial PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, week integer NOT NULL CHECK (week BETWEEN 1 AND 25), team_id uuid NOT NULL REFERENCES public.teams (id) ON DELETE CASCADE, slot_code text NOT NULL, player_key text NOT NULL, player_name text NOT NULL, position text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, week, team_id, slot_code), UNIQUE (season_id, week, team_id, player_key));
CREATE TABLE IF NOT EXISTS public.league_scoring_rules (id bigserial PRIMARY KEY, season_id uuid NOT NULL REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, category text NOT NULL, rule_key text NOT NULL, label text NOT NULL, points numeric(10, 4), rate_value numeric(10, 4), rate_unit text, threshold_value numeric(10, 4), notes text, rule_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT TRUE, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (season_id, rule_key));
CREATE TABLE IF NOT EXISTS public.league_weekly_host_settings (season_id uuid PRIMARY KEY REFERENCES public.league_seasons (id) ON DELETE CASCADE, room_id uuid NOT NULL REFERENCES public.rooms (id) ON DELETE CASCADE, scoring_type text NOT NULL DEFAULT 'head_to_head', start_scoring_week integer NOT NULL DEFAULT 1, fractional_points boolean NOT NULL DEFAULT TRUE, negative_points boolean NOT NULL DEFAULT TRUE, playoff_teams integer NOT NULL DEFAULT 6, playoff_weeks integer[] NOT NULL DEFAULT ARRAY[15, 16, 17], playoff_reseeding boolean NOT NULL DEFAULT FALSE, playoff_tiebreaker text, divisions boolean NOT NULL DEFAULT FALSE, median_matchup boolean NOT NULL DEFAULT FALSE, second_opponent boolean NOT NULL DEFAULT FALSE, max_season_acquisitions integer, max_weekly_acquisitions integer, max_season_trades integer, yahoo_trade_end_date date, waiver_time_days integer, waiver_type text, weekly_waivers text, post_draft_players text, cant_cut_provider text, lock_benched_players boolean NOT NULL DEFAULT FALSE, lock_eliminated_teams boolean NOT NULL DEFAULT FALSE, public_viewable boolean NOT NULL DEFAULT FALSE, updated_at timestamptz NOT NULL DEFAULT now());